                        best_i, best_j = i, j
            if best_gain > 1e-12:
                routes[ri] = r[:best_i + 1] + r[best_i + 1:best_j + 1][::-1] + r[best_j + 1:]
                improved = True

        # relocate from longer to shorter routes if feasible and better
        for a in range(len(routes)):
            for b in range(len(routes)):
                if a == b:
                    continue
                ra = routes[a]
                rb = routes[b]
                if not ra:
                    continue
                la = route_load(ra)
                lb = route_load(rb)
                for idx, c in enumerate(list(ra)):
                    d = demand_of(c)
                    if lb + d > capacity:
                        continue
                    best_ins = None
                    best_pos = 0
                    for p in range(len(rb) + 1):
                        prev = 0 if p == 0 else rb[p - 1]
                        nxt = 0 if p == len(rb) else rb[p]
                        delta = dist_id(prev, c) + dist_id(c, nxt) - dist_id(prev, nxt)
                        if best_ins is None or delta < best_ins:
                            best_ins = delta
                            best_pos = p
                    # compare with removal cost from ra
                    prev_a = 0 if idx == 0 else ra[idx - 1]
                    nxt_a = 0 if idx == len(ra) - 1 else ra[idx + 1]
                    rem_gain = dist_id(prev_a, c) + dist_id(c, nxt_a) - dist_id(prev_a, nxt_a)
                    if best_ins is not None and rem_gain > best_ins + 1e-12:
                        rb.insert(best_pos, c)
                        del ra[idx]
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break

        routes = [r for r in routes if r]

    # final cleanup: ensure no duplicates and all customers present
    present = {}
    final_routes = []
    for r in routes:
        nr = []
        for c in r:
            if c != 0 and c not in present:
                present[c] = 1
                nr.append(c)
        if nr:
            final_routes.append(nr)

    for c in ordered:
        if c not in present:
            # append as feasible singleton or to any feasible route
            d = demand_of(c)
            best_i = -1
            best_p = 0
            best_delta = None
            for i, r in enumerate(final_routes):
                if route_load(r) + d > capacity:
                    continue
                for p in range(len(r) + 1):
                    prev = 0 if p == 0 else r[p - 1]
                    nxt = 0 if p == len(r) else r[p]
                    delta = dist_id(prev, c) + dist_id(c, nxt) - dist_id(prev, nxt)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_i = i
                        best_p = p
            if best_i >= 0:
                final_routes[best_i].insert(best_p, c)
            else:
                final_routes.append([c])

    return final_routes
